module multi_pipe_4bit(
    input clk, 
    input rst_n, 
    input [3:0] mul_a, 
    input [3:0] mul_b, 
    output [7:0] mul_out
);
    // Extension of input signals
    wire [7:0] mul_a_ext, mul_b_ext;
    assign mul_a_ext = {{(4){1'b0}}, mul_a};
    assign mul_b_ext = {{(4){1'b0}}, mul_b};

    // Generate partial products
    wire [7:0] partial_products [3:0];
    genvar i;
    generate
        for(i = 0; i < 4; i=i+1) begin : gen_partial_products
            assign partial_products[i] = mul_b_ext[i] ? (mul_a_ext << i) : 'd0;
        end
    endgenerate

    // Registers to store intermediate sums
    reg [7:0] sum_reg [3:0];
    integer j;
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            for(j = 0; j < 4; j=j+1) begin
                sum_reg[j] <= 0;
            end
        end else begin
            for(j = 0; j < 4; j=j+1) begin
                sum_reg[j] <= partial_products[j];
            end
        end
    end

    // Register to store final product
    reg [7:0] mul_out_reg;
    always @(posedge clk or negedge rst_n) begin
        if(!rst_n) begin
            mul_out_reg <= 0;
        end else begin
            mul_out_reg <= sum_reg[0] + sum_reg[1] + sum_reg[2] + sum_reg[3];
        end
    end

    // Assign final product output
    assign mul_out = mul_out_reg;
endmodule
